"""Answers are generated by server-side tasks, not by the HTTP request that asked for them.

Closing the tab or losing the connection only detaches the viewer: the answer (and any scan
analysis it runs) keeps going and is saved. Opening the conversation again replays the events
so far and follows the rest live. Only the Stop button ends a run early.

Runs live in the API process, so the API is served by one process (the default here). A
multi-process deployment would move this buffer to Redis streams.
"""

from __future__ import annotations

import asyncio
import contextlib
import logging
from collections.abc import AsyncIterator

log = logging.getLogger(__name__)
KEEP_FINISHED_SECONDS = 120


class Run:
    def __init__(self, thread_id: str):
        self.thread_id = thread_id
        self.events: list[dict] = []
        self.finished = False
        self.changed = asyncio.Event()
        self.task: asyncio.Task | None = None

    def push(self, event: dict) -> None:
        self.events.append(event)
        self.changed.set()

    async def follow(self, start: int = 0) -> AsyncIterator[dict]:
        """All events from `start`, then live ones until the run ends."""
        index = start
        while True:
            while index < len(self.events):
                yield self.events[index]
                index += 1
            if self.finished:
                return
            self.changed.clear()
            if index < len(self.events) or self.finished:
                continue
            await self.changed.wait()


class RunBusy(RuntimeError):
    pass


class Runs:
    def __init__(self) -> None:
        self._runs: dict[str, Run] = {}

    def active(self, thread_id: str) -> Run | None:
        run = self._runs.get(thread_id)
        return run if run and not run.finished else None

    def latest(self, thread_id: str) -> Run | None:
        return self._runs.get(thread_id)

    def running_ids(self) -> set[str]:
        return {tid for tid, run in self._runs.items() if not run.finished}

    def start(self, thread_id: str, events: AsyncIterator[dict]) -> Run:
        if self.active(thread_id):
            raise RunBusy("An answer is still being written in this conversation.")
        run = Run(thread_id)
        self._runs[thread_id] = run
        run.task = asyncio.get_running_loop().create_task(self._drive(run, events))
        return run

    async def _drive(self, run: Run, events: AsyncIterator[dict]) -> None:
        try:
            async for event in events:
                run.push(event)
        except asyncio.CancelledError:
            with contextlib.suppress(Exception):
                await events.aclose()  # saves the partial answer as "stopped"
            run.push({"type": "stopped"})
        except Exception:
            log.exception("chat run failed")
            run.push({"type": "error", "message": "The answer could not be completed."})
        finally:
            run.finished = True
            run.changed.set()
            asyncio.get_running_loop().call_later(KEEP_FINISHED_SECONDS, self._forget, run)

    def _forget(self, run: Run) -> None:
        if self._runs.get(run.thread_id) is run:
            del self._runs[run.thread_id]

    async def stop(self, thread_id: str) -> bool:
        run = self.active(thread_id)
        if run is None or run.task is None:
            return False
        run.task.cancel()
        with contextlib.suppress(asyncio.CancelledError, Exception):
            await run.task
        return True

    def clear(self) -> None:
        for run in self._runs.values():
            if run.task and not run.task.done():
                run.task.cancel()
        self._runs.clear()


runs = Runs()
